import{_ as t,o as l,c as e,a2 as i}from"./chunks/framework.DxJTYR_a.js";const g=JSON.parse('{"title":"사내 메신저 (실시간 채팅)","description":"","frontmatter":{},"headers":[],"relativePath":"intro/chat.md","filePath":"intro/chat.md","lastUpdated":1791611975000}'),r={name:"intro/chat.md"};function n(s,a,o,d,h,c){return l(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="사내-메신저-실시간-채팅" tabindex="-1">사내 메신저 (실시간 채팅) <a class="header-anchor" href="#사내-메신저-실시간-채팅" aria-label="Permalink to &quot;사내 메신저 (실시간 채팅)&quot;">​</a></h1><p>IBS 사내 메신저는 웹과 모바일 앱 어디서나 전사 임직원 및 프로젝트 구성원들과 실시간으로 소통할 수 있는 협업 도구입니다. 프로젝트별 자동 생성되는 공용 채널, 1:1 대화, 개인 메모 공간을 지원하며, 업무 중 발생한 문서와 미디어를 영구 보관하여 신속하게 찾아볼 수 있습니다.</p><h2 id="진입-방법" tabindex="-1">진입 방법 <a class="header-anchor" href="#진입-방법" aria-label="Permalink to &quot;진입 방법&quot;">​</a></h2><h3 id="데스크톱-웹-pc" tabindex="-1">데스크톱 웹 (PC) <a class="header-anchor" href="#데스크톱-웹-pc" aria-label="Permalink to &quot;데스크톱 웹 (PC)&quot;">​</a></h3><ul><li>상단 내비게이션 바 우측의 <strong>메신저 아이콘</strong>(<span class="mdi mdi-chat-processing-outline"></span>)을 클릭합니다.</li><li>화면 우측에서 슬라이드 드로어 (Drawer) 형태로 열리며, 현재 작업 중인 페이지의 흐름을 방해하지 않고 소통할 수 있습니다.</li><li>상단 헤더 우측의 <strong>닫기 버튼</strong>(<span class="mdi mdi-close"></span>)을 누르면 드로어가 닫힙니다.</li></ul><h3 id="모바일-앱-ios-android" tabindex="-1">모바일 앱 (iOS / Android) <a class="header-anchor" href="#모바일-앱-ios-android" aria-label="Permalink to &quot;모바일 앱 (iOS / Android)&quot;">​</a></h3><ul><li>앱 화면 최상단 글로벌 헤더 (앱바) 우측의 <strong>메신저 아이콘</strong>(<span class="mdi mdi-message-text-outline"></span>)을 탭합니다.</li><li>전체 화면 채팅 목록 및 대화방으로 진입하며, 실시간 푸시 알림 수신 시 알림을 직접 탭하여 해당 대화방으로 바로 이동할 수도 있습니다.</li></ul><h2 id="대화방-유형" tabindex="-1">대화방 유형 <a class="header-anchor" href="#대화방-유형" aria-label="Permalink to &quot;대화방 유형&quot;">​</a></h2><p>IBS 사내 메신저는 목적에 따라 3가지 대화방을 제공합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">대화방 구분</th><th style="text-align:center;">아이콘</th><th style="text-align:left;">설명</th><th style="text-align:left;">참여 대상</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>공용 채널</strong></td><td style="text-align:center;"><span class="mdi mdi-pound"></span></td><td style="text-align:left;">프로젝트(워크스페이스) 단위로 자동 개설되는 전체 소통 공간</td><td style="text-align:left;">해당 프로젝트 참여 멤버 전원</td></tr><tr><td style="text-align:left;"><strong>1:1 대화</strong></td><td style="text-align:center;"><span class="mdi mdi-account"></span></td><td style="text-align:left;">임직원 간의 개별 비공개 업무 대화</td><td style="text-align:left;">초대한 상대방 및 본인 (2인)</td></tr><tr><td style="text-align:left;"><strong>나와의 채팅</strong></td><td style="text-align:center;"><span class="mdi mdi-bookmark-check"></span></td><td style="text-align:left;">개인 업무 메모, 링크, 임시 파일 보관을 위한 전용 공간</td><td style="text-align:left;">본인 전용 (외부 노출 없음)</td></tr></tbody></table><h3 id="_1-공용-채널-프로젝트명" tabindex="-1">1. 공용 채널 (#프로젝트명) <a class="header-anchor" href="#_1-공용-채널-프로젝트명" aria-label="Permalink to &quot;1. 공용 채널 (#프로젝트명)&quot;">​</a></h3><ul><li>프로젝트 (워크스페이스)가 등록되면 해당 프로젝트의 기본 소통 채널이 자동으로 연동됩니다.</li><li>프로젝트에 소속된 모든 멤버가 자유롭게 의견을 나누고 공지사항을 공유할 수 있습니다.</li></ul><h3 id="_2-새-1-1-대화-시작-및-나가기" tabindex="-1">2. 새 1:1 대화 시작 및 나가기 <a class="header-anchor" href="#_2-새-1-1-대화-시작-및-나가기" aria-label="Permalink to &quot;2. 새 1:1 대화 시작 및 나가기&quot;">​</a></h3><ul><li><strong>새 대화 시작</strong>: 대화방 목록 상단의 <strong>새 1:1 대화 버튼</strong>(<span class="mdi mdi-account-plus-outline"></span>)을 클릭한 후, 사용자 목록에서 대화할 동료를 선택합니다.</li><li><strong>대화방 나가기</strong>: 1:1 대화방 헤더 우측의 <strong>나가기 버튼</strong>(<span class="mdi mdi-exit-to-app"></span>)을 누르면 내 대화방 목록에서 숨김 처리됩니다. 상대방이 새 메시지를 보내면 목록에 다시 표시됩니다.</li></ul><h3 id="_3-나와의-채팅" tabindex="-1">3. 나와의 채팅 <a class="header-anchor" href="#_3-나와의-채팅" aria-label="Permalink to &quot;3. 나와의 채팅&quot;">​</a></h3><ul><li>대화방 목록 상단에 항상 고정 표출됩니다.</li><li>업무 중 기억해야 할 메모, 확인해야 할 링크, 임시 파일이나 이미지를 나만의 공간에 안전하게 스크랩해 둘 수 있습니다.</li></ul><h2 id="주요-메시지-기능" tabindex="-1">주요 메시지 기능 <a class="header-anchor" href="#주요-메시지-기능" aria-label="Permalink to &quot;주요 메시지 기능&quot;">​</a></h2><h3 id="_1-실시간-메시지-전송-및-읽음-확인" tabindex="-1">1. 실시간 메시지 전송 및 읽음 확인 <a class="header-anchor" href="#_1-실시간-메시지-전송-및-읽음-확인" aria-label="Permalink to &quot;1. 실시간 메시지 전송 및 읽음 확인&quot;">​</a></h3><ul><li><strong>실시간 동기화</strong>: 상대방이 작성한 메시지가 별도의 새로고침 없이 화면에 즉시 표시됩니다.</li><li><strong>상대방 입력 표시</strong>: 대화 상대가 메시지를 입력 중일 때 입력창 상단에 실시간으로 입력 중 표시가 나타납니다.</li><li><strong>안 읽은 멤버 수</strong>: 전송된 메시지 옆에 아직 확인하지 않은 참여자 수가 숫자로 표시됩니다.</li></ul><h3 id="_2-특정-메시지-답장-reply" tabindex="-1">2. 특정 메시지 답장 (Reply) <a class="header-anchor" href="#_2-특정-메시지-답장-reply" aria-label="Permalink to &quot;2. 특정 메시지 답장 (Reply)&quot;">​</a></h3><ul><li>메시지에 마우스를 올리거나 탭한 뒤 <strong>답장 아이콘</strong>을 클릭하면 해당 메시지가 입력창 상단에 인용 카드로 표시됩니다.</li><li>인용 카드가 연결된 상태에서 텍스트나 파일을 전송하면, 원본 메시지와 맥락이 연결되어 무엇에 대한 답변인지 명확하게 확인할 수 있습니다.</li></ul><h3 id="_3-파일-및-사진-첨부" tabindex="-1">3. 파일 및 사진 첨부 <a class="header-anchor" href="#_3-파일-및-사진-첨부" aria-label="Permalink to &quot;3. 파일 및 사진 첨부&quot;">​</a></h3><ul><li>입력창 좌측의 <strong>클립 아이콘</strong>(<span class="mdi mdi-paperclip"></span>)을 눌러 문서 (PDF, Excel, Word 등)나 현장 사진/동영상을 첨부할 수 있습니다.</li><li>전송된 이미지는 채팅방 내에서 썸네일 미리보기를 제공하며, 클릭 시 원본 크기로 확인하거나 다운로드할 수 있습니다.</li></ul><h3 id="_4-메시지-삭제" tabindex="-1">4. 메시지 삭제 <a class="header-anchor" href="#_4-메시지-삭제" aria-label="Permalink to &quot;4. 메시지 삭제&quot;">​</a></h3><ul><li>본인이 작성한 메시지의 메뉴에서 <strong>삭제</strong>를 선택하면 대화방에서 즉시 제거됩니다.</li></ul><h2 id="검색-및-보관함-활용" tabindex="-1">검색 및 보관함 활용 <a class="header-anchor" href="#검색-및-보관함-활용" aria-label="Permalink to &quot;검색 및 보관함 활용&quot;">​</a></h2><h3 id="_1-대화방-내-검색" tabindex="-1">1. 대화방 내 검색 <a class="header-anchor" href="#_1-대화방-내-검색" aria-label="Permalink to &quot;1. 대화방 내 검색&quot;">​</a></h3><ul><li>대화방 상단 헤더의 <strong>검색 아이콘</strong>(<span class="mdi mdi-magnify"></span>)을 클릭하면 검색창이 나타납니다.</li><li>찾고자 하는 키워드를 입력하면 서버 전체 메시지 데이터베이스에서 일치하는 메시지를 실시간으로 검색합니다.</li><li><strong>위/아래 방향키 버튼</strong>을 눌러 이전/다음 검색 결과로 빠르게 이동할 수 있으며, 해당 시점의 전후 대화 맥락을 함께 조회할 수 있습니다.</li></ul><h3 id="_2-통합-전역-검색" tabindex="-1">2. 통합 전역 검색 <a class="header-anchor" href="#_2-통합-전역-검색" aria-label="Permalink to &quot;2. 통합 전역 검색&quot;">​</a></h3><ul><li>대화방 목록 화면에서 상단의 <strong>검색 버튼</strong>을 누르면 내가 속한 모든 대화방을 대상으로 통합 키워드 검색을 수행할 수 있습니다.</li></ul><h3 id="_3-파일-미디어-보관함-서랍" tabindex="-1">3. 파일/미디어 보관함 서랍 <a class="header-anchor" href="#_3-파일-미디어-보관함-서랍" aria-label="Permalink to &quot;3. 파일/미디어 보관함 서랍&quot;">​</a></h3><ul><li>대화방 상단 헤더의 <strong>폴더 아이콘</strong>(<span class="mdi mdi-folder-open-outline"></span>)을 클릭하면 우측에 전용 파일 보관함 서랍이 열립니다.</li><li>대화방에서 공유된 모든 파일과 사진만을 일목요연하게 모아서 열람하고 다운로드할 수 있어, 지난 첨부파일을 찾기 위해 과거 대화를 일일이 스크롤할 필요가 없습니다.</li></ul><h2 id="알림-및-연결-편의-기능" tabindex="-1">알림 및 연결 편의 기능 <a class="header-anchor" href="#알림-및-연결-편의-기능" aria-label="Permalink to &quot;알림 및 연결 편의 기능&quot;">​</a></h2><h3 id="최신-대화로-복귀-버튼" tabindex="-1">최신 대화로 복귀 버튼 <a class="header-anchor" href="#최신-대화로-복귀-버튼" aria-label="Permalink to &quot;최신 대화로 복귀 버튼&quot;">​</a></h3><ul><li>과거 대화를 검색하거나 스크롤하여 위쪽을 열람하고 있을 때 새 메시지가 수신되어도 화면이 멋대로 맨 아래로 튀지 않도록 보호됩니다.</li><li>하단에 나타나는 <strong>최신 대화로 이동 버튼</strong>(<span class="mdi mdi-chevron-down"></span>)을 클릭하면 언제든지 즉시 가장 최근 대화 위치로 복귀합니다.</li></ul><h3 id="모바일-백그라운드-푸시-알림" tabindex="-1">모바일 백그라운드 푸시 알림 <a class="header-anchor" href="#모바일-백그라운드-푸시-알림" aria-label="Permalink to &quot;모바일 백그라운드 푸시 알림&quot;">​</a></h3><ul><li>모바일 앱이 백그라운드에 있거나 화면이 꺼져 있어도 새로운 메시지가 도착하면 헤드업 푸시 알림이 발송됩니다.</li><li>알림을 탭하면 즉시 해당 대화방으로 바로 이동합니다.</li></ul>',37)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
